import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

const formatter = new Intl.NumberFormat("vi-VN", {
  style: "currency",
  currency: "VND",
  maximumFractionDigits: 0,
})

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatVND(value: number) {
  return formatter.format(value)
}

const windows1252CodePointToByte: Record<number, number> = {
  0x20ac: 0x80,
  0x201a: 0x82,
  0x0192: 0x83,
  0x201e: 0x84,
  0x2026: 0x85,
  0x2020: 0x86,
  0x2021: 0x87,
  0x02c6: 0x88,
  0x2030: 0x89,
  0x0160: 0x8a,
  0x2039: 0x8b,
  0x0152: 0x8c,
  0x017d: 0x8e,
  0x2018: 0x91,
  0x2019: 0x92,
  0x201c: 0x93,
  0x201d: 0x94,
  0x2022: 0x95,
  0x2013: 0x96,
  0x2014: 0x97,
  0x02dc: 0x98,
  0x2122: 0x99,
  0x0161: 0x9a,
  0x203a: 0x9b,
  0x0153: 0x9c,
  0x017e: 0x9e,
  0x0178: 0x9f,
}

export function fixVietnameseText(value?: string | null) {
  if (!value) return ""
  if (!/[ÃÂÄÆáºá»]/.test(value)) return value

  try {
    const bytes = Array.from(value, (char) => {
      const codePoint = char.codePointAt(0) ?? 0
      return windows1252CodePointToByte[codePoint] ?? codePoint
    })

    const decoded = new TextDecoder("utf-8", { fatal: true }).decode(
      new Uint8Array(bytes)
    )

    return decoded.includes("�") ? value : decoded
  } catch {
    return value
  }
}

export function productImageUrl(image?: string | null) {
  if (!image) {
    return "/images/NoImage.jpg"
  }

  if (image.startsWith("http://") || image.startsWith("https://")) {
    try {
      const url = new URL(image)

      if (url.pathname.startsWith("/storage/")) {
        return `/api/product-images/${url.pathname.replace(/^\/storage\//, "")}${url.search}`
      }

      if (url.pathname.startsWith("/api/product-images/")) {
        return `${url.pathname}${url.search}`
      }
    } catch {
      return image
    }

    return image
  }

  if (image.startsWith("data:") || image.startsWith("/images/")) {
    return image
  }

  if (image.startsWith("/storage/")) {
    return `/api/product-images/${image.replace(/^\/storage\//, "")}`
  }

  if (image.startsWith("storage/")) {
    return `/api/product-images/${image.replace(/^storage\//, "")}`
  }

  return `/api/product-images/${image.replace(/^\/+/, "")}`
}
