import ProductCard from "./ProductCard";
import type { Product } from "@/types/product";
import Link from "next/link";
import { ArrowRight } from "lucide-react";

interface ProductListProps {
  products: Product[];
  title?: string;
  eyebrow?: string;
  id?: string;
  viewMoreLink?: string;
}

export default function ProductList({ products, title, eyebrow, id, viewMoreLink }: ProductListProps) {
  return (
    <section id={id} className="scroll-mt-28">
      {title && (
        <div className="mb-9 grid gap-5 border-b border-[#d6bd7a]/20 pb-6 lg:grid-cols-[1fr_auto] lg:items-end">
          <div>
            {eyebrow && <p className="text-xs font-semibold uppercase tracking-[0.3em] text-[#d6bd7a]">{eyebrow}</p>}
            <h2 className="mt-3 font-serif text-4xl font-light tracking-normal text-[#f7efe1] sm:text-5xl">{title}</h2>
          </div>
          {viewMoreLink && (
            <Link href={viewMoreLink} className="inline-flex items-center justify-center gap-3 border border-[#d6bd7a]/35 px-5 py-3 text-xs font-bold uppercase tracking-[0.2em] text-[#f7efe1] transition hover:border-[#d6bd7a] hover:bg-[#d6bd7a] hover:text-black">
              Xem thêm
              <ArrowRight className="h-4 w-4" />
            </Link>
          )}
        </div>
      )}
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {products.length > 0 ? (
          products.map((product) => <ProductCard key={product.id} product={product} />)
        ) : (
          <div className="col-span-full border border-dashed border-[#d6bd7a]/30 bg-black/20 px-6 py-16 text-center">
            <h3 className="font-serif text-2xl text-[#f7efe1]">Chưa có sản phẩm phù hợp</h3>
            <p className="mt-3 text-[#cfc4ad]/75">Bộ sưu tập này đang được cập nhật.</p>
          </div>
        )}
      </div>
    </section>
  );
}
